function isWhitelistedUrl(url) {
  if (!url) return false;
  const u = url.toLowerCase();
  return u.includes('marcaopersonal.com') || u.includes('instagram.com/marcaopersonalfitness') || u.includes('shopee.com.br') || u.includes('s.shopee.com.br') || u.includes('braip.com') || u.includes('ev.braip.com') || u.includes('stripe.com') || u.includes('buy.stripe.com');
}

function sanitizarTextoLinks(texto) {
  if (!texto) return '';
  let limpo = texto;
  // 1. Remove markdown links de pesquisa tipo [calori.com](https://...) completamente
  limpo = limpo.replace(/\[([^\]]+)\]\((https?:\/\/[^\s\)]+)\)/gi, (m, txt, url) => isWhitelistedUrl(url) ? url : '');
  // 2. Remove frases introdutorias de links externos
  limpo = limpo.replace(/\b(?:veja mais em|veja em|acesse em|acesse|fonte:|dispon[ií]vel em|conforme|segundo o site|link:)\s*https?:\/\/[^\s\)\],]+/gi, '');
  // 3. Remove URLs restantes nao whitelisted
  limpo = limpo.replace(/https?:\/\/[^\s\)\],]+/gi, (url) => isWhitelistedUrl(url) ? url : '');
  // 4. Remove dominios soltos de fontes de pesquisa
  limpo = limpo.replace(/\b(?:[a-zA-Z0-9-]+\.)+(?:gov\.br|org\.br|com\.br|edu\.br|org|net|info|io|ai|com)\b(?:\/[^\s\)\],]*)?/gi, (domain) => isWhitelistedUrl(domain) ? domain : '');
  // 4.5. Remove citações em colchetes de pesquisa web / grounding (ex: [anad.org.br], [em.com.br], [1], [2])
  limpo = limpo.replace(/\s*\[(?:[a-zA-Z0-9-]+\.[a-zA-Z0-9-._]+|\d+)\]/g, '');

  // 5. Limpa pontuacoes orfas
  limpo = limpo.replace(/\[\s*\]/g, '').replace(/\(\s*\)/g, '');
  limpo = limpo.replace(/,\s*,/g, ',').replace(/\.\s*\./g, '.');
  return limpo.replace(/[ \t]{2,}/g, ' ').trim();
}

