if (!rawContent || rawContent.length === 0) {
  try {
    const gemKey = "GEMINI_API_KEY_ENV";
    const msgs = (info && info.messages) || [];
    let sysInst = "";
    const contents = [];

    function _extTxt(c) {
      if (typeof c === 'string') return c;
      if (Array.isArray(c)) {
        return c.map(i => (typeof i === 'object' ? (i.text || '') : String(i))).join('\n');
      }
      return String(c || '');
    }

    function _extParts(content) {
      const parts = [];
      if (typeof content === 'string') {
        if (content.trim()) parts.push({ text: content.trim() });
      } else if (Array.isArray(content)) {
        for (const it of content) {
          if (it && typeof it === 'object') {
            if (it.type === 'text' && it.text && it.text.trim()) {
              parts.push({ text: it.text.trim() });
            } else if (it.type === 'image_url') {
              const url = (it.image_url && it.image_url.url) || '';
              if (url.includes(';base64,')) {
                const sp = url.split(';base64,');
                const mime = sp[0].replace('data:', '');
                parts.push({ inline_data: { mime_type: mime, data: sp[1] } });
              } else if (url.startsWith('http')) {
                parts.push({ text: `[Imagem: ${url}]` });
              }
            } else if (it.type === 'input_audio') {
              const a = it.input_audio || {};
              const b64 = a.data || '';
              const fmt = a.format || 'ogg';
              const mime = fmt === 'ogg' ? 'audio/ogg' : `audio/${fmt}`;
              if (b64) {
                parts.push({ inline_data: { mime_type: mime, data: b64 } });
              }
            }
          } else if (it) {
            parts.push({ text: String(it) });
          }
        }
      } else if (content) {
        parts.push({ text: String(content) });
      }
      return parts;
    }

