      try {
        const gemRes = await this.helpers.httpRequest({
          method: 'POST',
          url: `https://generativelanguage.googleapis.com/v1beta/models/${mod}:generateContent?key=${gemKey}`,
          headers: { 'Content-Type': 'application/json' },
          body: gemPayload,
          json: true,
          timeout: 25000
        });

        if (gemRes && gemRes.candidates && gemRes.candidates[0] && gemRes.candidates[0].content && gemRes.candidates[0].content.parts && gemRes.candidates[0].content.parts[0] && gemRes.candidates[0].content.parts[0].text) {
