function isMensagemEncerramento(texto) {
  if (!texto) return false;
  let t = texto.trim().toLowerCase();

  // Se tem pergunta ou dúvida, não é encerramento
  if (t.includes('?') || /\b(como|quanto|quantos|qual|quais|onde|quando|por que|pq|oq|o que|explica|explique|d[uú]vida)\b/i.test(t)) {
    return false;
  }

  t = t.replace(/[!?,;.]+/g, ' ').replace(/\s+/g, ' ').trim();
  const palavras = t.split(' ').filter(w => w.length > 0);
  if (palavras.length === 0 || palavras.length > 6) return false;

  const termosEncerramento = new Set([
    'ok', 'blz', 'beleza', 'valeu', 'vlw', 'obrigado', 'obrigada', 'brigado', 'brigada', 'obg',
    'show', 'top', 'combinado', 'fechado', 'entendi', 'entendido', 'certo',
    'tranquilo', 'tmj', 'tamo', 'flw', 'valew', 'bele', 'suave', 'perfeito', 'otimo', 'ótimo',
    'sempre', 'partiu', 'bora', 'deixa', 'comigo'
  ]);

  if (
    t === 'ta bom' || t === 'tá bom' || t === 'ta bem' || t === 'tá bem' || 
    t === 'show de bola' || t === 'tamo junto' || t === 'deixa comigo' || 
    t === 'pode deixar' || t === 'pode deixar comigo' || t === 'com certeza' || 
    t === 'vou fazer' || t === 'vou la' || t === 'vou lá' || t === 'sempre'
  ) return true;

  return palavras.some(p => termosEncerramento.has(p));
}

function devePesquisarNaWeb(texto, info = {}) {
  if (!texto && !info.isFoto && !info.isFotoReal) return false;
  let t = (texto || '').trim().toLowerCase();

  // Se for mensagem de encerramento, NUNCA pesquisa
  if (isMensagemEncerramento(t)) return false;

  // Se for foto de prato/refeição, SEMPRE pesquisa para identificar nutrientes e formular sugestões sob medida
  if (info.isFoto || info.isFotoReal) return true;

  t = t.replace(/[!?,;.]+/g, ' ').replace(/\s+/g, ' ').trim();

  const tokensCasuais = new Set([
    'ok', 'tudo', 'bem', 'bom', 'td', 'certo', 'cima', 'beleza', 'blz', 'tranquilo', 
    'como', 'vai', 'voce', 'você', 'esta', 'está', 'e', 'ai', 'aí', 'opa', 'oi', 
    'ola', 'olá', 'bom', 'dia', 'boa', 'tarde', 'noite', 'valeu', 'obrigado', 
    'obrigada', 'combinado', 'fechado', 'sim', 'ta', 'tá', 'show', 'top', 'tmj', 
    'marcao', 'marcão', 'fala', 'irmão', 'irmao', 'parceiro', 'campeão', 'campeao'
  ]);

  const palavras = t.split(' ').filter(w => w.length > 0);
  const todasSaoCasuais = palavras.length > 0 && palavras.every(w => tokensCasuais.has(w));
  if (todasSaoCasuais) return false;

  if (/^(treinei|treino pago|t[aá] pago|fui treinar|acabei o treino|hoje tem|concordo|fechado)$/i.test(t)) {
    return false;
  }

  // 1. Dificuldade de rotina, constância, foco ou desânimo
  const termosDificuldade = /\b(dificuldade|dif[ií]cil|const[aâ]ncia|n[aã]o consigo|n[aã]o estou conseguindo|falhei|escorreguei|sem foco|desanimad[ao]|sem tempo|rotina corrida|pregui[cç]a|pesado|cansad[ao]|fome|vontade de comer|compuls[aã]o|doce|a[cç][uú]car)\b/i.test(t);

  // 2. Dúvidas sobre o que comer, substituições, receitas, cardápio e refeições
  const termosAlimentacao = /\b(o que comer|oque comer|receita|lanche|substitui[cç][aã]o|substituir|trocar|comida|card[aá]pio|almo[cç]o|jantar|caf[eé]|refei[cç][aã]o|prato|arroz|feij[aã]o|frango|carne|ovo|ovos|salada|legume|fruta|whey|creatina|prote[ií]na|carbo|carboidrato|gordura|caloria|macros|suplemento)\b/i.test(t);

  // 3. Dores articulares, limitações físicas e adaptação de exercícios
  const termosSaudeDor = /\b(dor|les[aã]o|doendo|joelho|coluna|lombar|ombro|cotovelo|punho|articula[cç][aã]o|inflama[cç][aã]o|tendinite|press[aã]o|rem[eé]dio|cora[cç][aã]o|peso estagnado|n[aã]o emagre[cç]o|n[aã]o cres[cç]o)\b/i.test(t);

  // 4. Termos interrogativos ou busca explícita
  const temInterrogacao = (texto || '').includes('?');
  const termosPergunta = /\b(o que|oq|qual|quais|como|por que|pq|quanto|quantos|quem|onde|quando|pesquisa|pesquise|busca|busque|explica|explique|sabe me dizer|me tira uma d[uú]vida|d[uú]vida|voc[eê] conhece|voce conhece|indica|recomenda|vale a pena|funciona|estudo|pesquisa recente)\b/i.test(t);

  return termosDificuldade || termosAlimentacao || termosSaudeDor || (temInterrogacao && palavras.length >= 2) || termosPergunta;
}

