    content: '🚨 REGRA INVIOLÁVEL DE ENCERRAMENTO DE CONVERSA (UMA LINHA SÓ OU 1 FIGURINHA):\n' +
      'O aluno ou lead enviou uma mensagem de confirmação, fechamento ou agradecimento ("' + (prev.textoRecebido || '') + '").\n' +
      'O ASSUNTO TERMINOU COMPLETAMENTE!\n' +
      'É TERMINANTEMENTE PROIBIDO estender a conversa, fazer perguntas de continuidade, oferecer novos assuntos, vender produtos ou mandar textão!\n' +
      'A sua resposta DEVE SER EXCLUSIVAMENTE UMA DAS DUAS OPÇÕES:\n' +
      'Opção 1) UMA LINHA CURTA ÚNICA: Responda em no máximo 1 linha (50 a 80 caracteres), encorajadora e contextualizada (ex: "Tamo junto! Bom descanso e foco no treino! 👊🔥" ou "Combinado! Qualquer coisa tô por aqui! 💪🦁"). Zero perguntas!\n' +
      'Opção 2) UMA FIGURINHA ÚNICA: envie apenas a tag de figurinha (<<<STICKER:JOINHA>>> ou <<<STICKER:FISTBUMP>>>) sem absolutamente nenhum texto junto!'
  });
} else if (devePesquisar) {
  messages.unshift({
    role: 'system',
    content: '🎯 INSTRUÇÃO DE PESQUISA WEB & SUGESTÕES PERSONALIZADAS (GROUNDING):\n' +
      'Você está usando pesquisa na web em tempo real para embasar suas respostas com o que há de mais atual na nutrição e treinamento físico.\n' +
      'REGRA ABSOLUTA 1: SEMPRE SUGERIR ALÉM DE CHAMAR A ATENÇÃO! Nunca apenas aponte erros ou falhas. Sempre forneça 1 a 2 sugestões práticas, viáveis e saborosas (substituições de alimentos, receitas rápidas fit, ajustes de porção ou adaptação de exercícios) personalizadas para a idade, gênero e limitações do aluno!\n' +
      'REGRA ABSOLUTA 2: FICA TERMINANTEMENTE PROIBIDO ENVIAR LINKS DAS PESQUISAS! Nunca inclua URLs externas, artigos científicos, links em markdown [site.com](url) ou números de citação [1]. Todo o conhecimento deve ser expresso com sua voz autêntica de treinador Marcão!\n' +
      'REGRA ABSOLUTA 3: Responda em múltiplos balões curtos (50 a 120 caracteres cada) separados por \\n\\n.'
  });
}

const payload = {
  model: modeloFinal,
  messages: messages,
  max_tokens: isEncerramento ? 60 : 350,
  temperature: isEncerramento ? 0.4 : 0.7
};

return [{
  json: {
    ...prev,
    messages: messages,
    openrouterPayload: payload,
    modeloEscolhido: modeloFinal,
    devePesquisar: devePesquisar,
    isEncerramento: isEncerramento,
    pediuAudio: Boolean(prev.isAudio || prev.pediuAudio),
    historicoPrevio: historico,
    historicoSalvar: historico,
    historico: historico
  }
}];

} catch (promptErr) {
  // BLINDAGEM DE RESPOSTA INFALÍVEL: Marcão nunca fica em silêncio
  console.error("ERRO INESPERADO EM MONTAR PROMPT:", promptErr);
  const fallbackModel = 'google/gemini-2.5-flash';
  const fallbackMessages = [
    {
      role: 'system',
      content: 'Você é o Treinador Marcão Personal AI, direto, vigoroso e focado em disciplina e musculação. Responda em 2 a 3 balões curtos (máximo 120 caracteres por balão) separados por quebra de linha dupla (\\n\\n).'
    },
    {
      role: 'user',
      content: (prev && prev.textoRecebido) ? prev.textoRecebido : 'Oi'
    }
  ];
  return [{
    json: {
      ...prev,
      messages: fallbackMessages,
      openrouterPayload: {
        model: fallbackModel,
        messages: fallbackMessages,
        max_tokens: 350,
        temperature: 0.7
      },
      modeloEscolhido: fallbackModel,
      devePesquisar: false,
      pediuAudio: prev ? prev.isAudio : false,
      historicoPrevio: historico,
      historicoSalvar: historico,
      historico: historico
    }
  }];
}

